CREATE OR REPLACE FUNCTION public.figure_guard_commit_new_images(p_id uuid, p_actor uuid, p_explanation text, p_option_analysis jsonb, p_memory_tip text, p_needs jsonb)
 RETURNS TABLE(status text, question_id text, explanation text, option_analysis jsonb, memory_tip text, model text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare saved record; lim public.figure_image_limits%rowtype; cfg public.figure_queue_config%rowtype; digest text;
begin
 select * into saved from public.ai_guard_commit(p_id,p_actor,p_explanation,p_option_analysis,p_memory_tip);
 if saved.status='inserted' then
  update public.question_explanation_overrides o set figure_status='awaiting_image_plan' where o.question_id=saved.question_id;
  -- A failed image plan cannot roll back an already paid, valid explanation.
  begin
   select * into lim from public.figure_image_limits where id=true for update;
   select * into cfg from public.figure_queue_config where id=true for update;
   digest:=encode(sha256(convert_to(saved.explanation,'UTF8')),'hex');
   if lim.capture and lim.captured<lim.max_new and (select count(*) from public.figure_queue_jobs)<cfg.max_rows
    and jsonb_typeof(p_needs)='object' and octet_length(p_needs::text)<=4096
    and p_needs->>'explanationHash'=digest and p_needs->>'revision' ~ '^[0-9a-f]{64}$'
    and jsonb_typeof(p_needs->'items')='array' and jsonb_array_length(p_needs->'items') between 1 and 3 then
    insert into public.figure_queue_jobs(request_id,question_id,explanation_sha256,state,figure_needs,needs_state,image_status)
    values(p_id,saved.question_id,digest,'pending',p_needs,'awaiting','awaiting_concept_review') on conflict do nothing;
    if found then
     update public.figure_image_limits set captured=captured+1 where id=true;
     update public.question_explanation_overrides o set figure_status='awaiting_concept_review' where o.question_id=saved.question_id;
    end if;
   end if;
  exception when others then
   update public.question_explanation_overrides o set figure_status='awaiting_image' where o.question_id=saved.question_id;
  end;
 end if;
 return query select saved.status,saved.question_id,saved.explanation,saved.option_analysis,saved.memory_tip,saved.model,saved.updated_at;
end $function$

CREATE OR REPLACE FUNCTION public.figure_image_review(p_id uuid, p_revision text, p_needs jsonb, p_reviewer uuid, p_method text DEFAULT 'manual'::text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare job public.figure_queue_jobs%rowtype; txt text; item jsonb;
begin
 select * into job from public.figure_queue_jobs where request_id=p_id for update;
 if not found or p_method is null or p_method not in ('manual','trusted_catalog','schema_query') or (p_method='manual' and p_reviewer is null) or (p_method='trusted_catalog' and (p_reviewer is not null or p_needs->>'reviewMethod' is distinct from 'trusted_catalog')) or (p_method='schema_query' and (p_reviewer is not null or p_needs->>'reviewMethod' is distinct from 'schema_query')) or job.state<>'pending' or job.needs_state<>'awaiting' or job.figure_needs->>'revision' is distinct from p_revision then return 'stale'; end if;
 select explanation into txt from public.question_explanation_overrides where question_id=job.question_id for share;
 if not found or encode(sha256(convert_to(txt,'UTF8')),'hex')<>job.explanation_sha256 then return 'stale'; end if;
 if p_needs->>'status' is distinct from 'approved' or p_needs->>'revision' is distinct from p_revision or p_needs->>'explanationHash' is distinct from job.explanation_sha256 or jsonb_typeof(p_needs->'items') is distinct from 'array' or octet_length(p_needs::text)>4096 or jsonb_array_length(p_needs->'items')<>jsonb_array_length(job.figure_needs->'items') then return 'invalid'; end if;
 for item in select value from jsonb_array_elements(p_needs->'items') loop
  if p_method='schema_query' and (item->>'searchScope' is distinct from 'general-medical' or item->>'medicalDomain' not in ('anatomy','physiology','biochemistry','microbiology','pathology','pharmacology') or item->>'medicalDomain' is null or item->>'query' is distinct from item->>'proposedQuery' or item->>'query' is null or length(item->>'query') not between 2 and 90 or item->>'query' !~ '^[a-z][a-z -]+$' or item->>'query' ~ '\m(patient|name|john|jane|smith|doe|address|email|phone|record|hospital|clinic|case|password|token|secret|key|ignore|instruction|upload|download|send|search|find|my|his|her|our|your|mr|mrs|dr)\M') then return 'invalid'; end if;
  if not ((p_method='schema_query' and item->>'catalogRevision'='schema-query-v1') or (p_method='manual' and item->>'catalogRevision'='reviewed-query-v1' and length(item->>'query') between 2 and 100 and item->>'query' ~ '^[A-Za-z一-鿿 ()-]+$') or (item->>'conceptId'='carotid-sheath' and item->>'query'='carotid sheath anatomy' and item->>'catalogRevision'='carotid-sheath-v1') or (item->>'conceptId'='carotid-sinus' and item->>'query'='carotid sinus anatomy OpenStax' and item->>'catalogRevision'='carotid-sinus-v1') or (item->>'conceptId'='dural-venous-sinuses' and item->>'query'='dural venous sinuses OpenStax' and item->>'catalogRevision'='dural-venous-sinuses-v1')) or not exists(select 1 from jsonb_array_elements(job.figure_needs->'items') x where x->>'sectionAnchor'=item->>'sectionAnchor' and x->>'sectionHash'=item->>'sectionHash' and x->>'sectionTitle'=item->>'sectionTitle' and x->>'caption'=item->>'caption') then return 'invalid'; end if;
 end loop;
 update public.figure_queue_jobs set figure_needs=p_needs,needs_state='approved',needs_reviewer=p_reviewer,needs_review_method=p_method,needs_reviewed_at=clock_timestamp(),image_status='ready_to_search' where request_id=p_id;
 return 'approved';
end $function$

CREATE OR REPLACE FUNCTION public.explanation_replacement_base(p_question text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare payload jsonb; shared jsonb; reviewed jsonb;
begin
 select to_jsonb(e) into shared from public.question_explanation_overrides e where question_id=p_question;
 select jsonb_build_object('question_id',p_question,'generation',s.generation,'manifest_sha256',s.manifest_sha256,'source_commit',s.source_commit)
 into reviewed from public.ai_guard_reviewed_state s join public.ai_guard_reviewed_questions q on q.generation=s.generation and q.question_id=p_question where s.id=true;
 payload:=jsonb_build_object('shared',shared,'reviewed_static_ref',reviewed);
 return payload||jsonb_build_object('version',encode(sha256(convert_to(payload::text,'UTF8')),'hex'));
end $function$

CREATE OR REPLACE FUNCTION public.explanation_replacement_status(p_actor uuid, p_question text, p_operation uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v public.explanation_replacement_versions%rowtype; current_row public.question_explanation_overrides%rowtype;
begin
 if p_actor is null or p_question is null or length(p_question) not between 1 and 200 then return jsonb_build_object('status','invalid'); end if;
 select * into current_row from public.question_explanation_overrides where question_id=p_question;
 if p_operation is null then
 return jsonb_build_object('status','ready','baseVersion',public.explanation_replacement_base(p_question)->>'version',
 'revision',current_row.replacement_revision,'canRestore',exists(select 1 from public.explanation_replacement_versions x
 where x.request_id=current_row.replacement_revision and x.actor_id=p_actor and x.committed_at is not null and x.restored_at is null));
 end if;
 select * into v from public.explanation_replacement_versions where request_id=p_operation and actor_id=p_actor and question_id=p_question;
 if not found then return jsonb_build_object('status','not_found'); end if;
 if v.restored_at is not null then return jsonb_build_object('status','restored','value',case when current_row.question_id is null then null else to_jsonb(current_row) end);end if;
 if v.committed_at is null then
 if exists(select 1 from public.ai_guard_requests where id=v.request_id and state='closed' and not result_committed) then return jsonb_build_object('status','not_written');end if;
 return jsonb_build_object('status','pending');end if;
 if current_row.replacement_revision is distinct from v.request_id then return jsonb_build_object('status','superseded','value',case when current_row.question_id is null then null else to_jsonb(current_row) end);end if;
 return jsonb_build_object('status','completed','value',to_jsonb(current_row));
end $function$

CREATE OR REPLACE FUNCTION public.ai_guard_commit_replacement(p_id uuid, p_actor uuid, p_explanation text, p_option_analysis jsonb, p_memory_tip text, p_needs jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.ai_guard_budget%rowtype; r public.ai_guard_requests%rowtype; v public.explanation_replacement_versions%rowtype;
 winner public.question_explanation_overrides%rowtype; n timestamptz:=clock_timestamp();
 lim public.figure_image_limits%rowtype; cfg public.figure_queue_config%rowtype; digest text; queued boolean:=false;
begin
 perform public.figure_text_commit_lock(p_id,p_actor);
 select * into b from public.ai_guard_budget where id=true for update;
 if not found then return jsonb_build_object('status','unavailable'); end if;
 select * into r from public.ai_guard_requests where id=p_id for update;
 if not found or r.state<>'active' or r.result_committed or p_actor is null or r.actor_id<>p_actor
 or r.call_limit<>1 or not exists(select 1 from public.ai_guard_reviewed_state s where s.id=true and s.generation=r.reviewed_generation)
 or p_explanation is null or length(trim(p_explanation))=0 or length(p_explanation)>100000
 or p_option_analysis is null or jsonb_typeof(p_option_analysis)<>'object' or length(p_option_analysis::text)>100000
 or length(coalesce(p_memory_tip,''))>100000
 or not exists(select 1 from public.ai_guard_calls c where c.request_id=p_id and c.seq=1 and c.state='settled')
 or exists(select 1 from public.ai_guard_calls c where c.request_id=p_id and c.state<>'settled') then return jsonb_build_object('status','unavailable'); end if;
 select * into v from public.explanation_replacement_versions where request_id=p_id and actor_id=p_actor and question_id=r.question_id for update;
 if not found or v.after_snapshot is not null then return jsonb_build_object('status','unavailable'); end if;
 if v.base_version is distinct from public.explanation_replacement_base(r.question_id)->>'version' then return jsonb_build_object('status','replacement_version_changed'); end if;
 -- The existing write barrier accepts this exact payload only in this transaction,
 -- after it has a private backup and a settled guard request. No session bypass flag.
 update public.explanation_replacement_versions set write_transaction=txid_current(),after_snapshot=jsonb_build_object(
 'explanation',p_explanation,'option_analysis',p_option_analysis,'memory_tip',p_memory_tip,'model',r.model,
 'replacement_revision',p_id,'updated_at',n,'figure_status','awaiting_image','reading_format','full-v1') where request_id=p_id;
 select * into winner from public.figure_text_commit_write(p_id,p_actor);
 update public.explanation_replacement_versions set after_snapshot=to_jsonb(winner),committed_at=n where request_id=p_id;
 update public.ai_guard_requests set result_committed=true where id=p_id;
 -- Text/archive are already valid. A queue failure never loses paid text.
 begin
  select * into lim from public.figure_image_limits where id=true for update;
  select * into cfg from public.figure_queue_config where id=true for update;
  digest:=encode(sha256(convert_to(winner.explanation,'UTF8')),'hex');
  if b.enabled and (b.verified_credit_expires_at>clock_timestamp() or public.explanation_sitewide_request_allowed(p_id,p_actor)) and lim.capture and cfg.capture_new
   and lim.captured<lim.max_new and (select count(*) from public.figure_queue_jobs)<cfg.max_rows
   and jsonb_typeof(p_needs)='object' and octet_length(p_needs::text)<=4096
   and p_needs->>'explanationHash'=digest and p_needs->>'revision' ~ '^[0-9a-f]{64}$'
   and jsonb_typeof(p_needs->'items')='array' and jsonb_array_length(p_needs->'items') between 1 and 3 then
   insert into public.figure_queue_jobs(request_id,question_id,explanation_sha256,state,figure_needs,needs_state,image_status)
   values(p_id,winner.question_id,digest,'pending',p_needs,'awaiting','awaiting_concept_review') on conflict do nothing;
   if found then
    update public.figure_image_limits set captured=captured+1 where id=true;
    queued:=true;
   end if;
  end if;
 exception when others then queued:=false;
 end;
 return jsonb_build_object('status','replaced','value',to_jsonb(winner),'figureQueued',queued);
end $function$

CREATE OR REPLACE FUNCTION public.ai_guard_commit(p_id uuid, p_actor uuid, p_explanation text, p_option_analysis jsonb, p_memory_tip text)
 RETURNS TABLE(status text, question_id text, explanation text, option_analysis jsonb, memory_tip text, model text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.ai_guard_budget%rowtype; r public.ai_guard_requests%rowtype;
        winner public.question_explanation_overrides%rowtype; inserted boolean := false; n timestamptz:=clock_timestamp();
begin
 -- Serialize against legacy row writers BEFORE budget lock to avoid tuple→budget inversion.
 lock table public.question_explanation_overrides in share row exclusive mode;
 select * into b from public.ai_guard_budget where id=true for update;
 if not found then return query select 'unavailable'::text,null::text,null::text,null::jsonb,null::text,null::text,null::timestamptz; return; end if;
 select * into r from public.ai_guard_requests ar where ar.id=p_id for update;
 if not found or r.state <> 'active' or r.result_committed or p_actor is null or r.actor_id <> p_actor
    or not exists(select 1 from public.ai_guard_reviewed_state rs where rs.id=true and rs.generation=r.reviewed_generation)
    or exists(select 1 from public.ai_guard_reviewed_questions rq where rq.question_id=r.question_id and rq.generation=r.reviewed_generation)
    or p_explanation is null or length(trim(p_explanation))=0 or length(p_explanation)>100000
    or p_option_analysis is null or jsonb_typeof(p_option_analysis) <> 'object'
    or length(p_option_analysis::text)>100000 or length(coalesce(p_memory_tip,''))>100000
    or not exists(select 1 from public.ai_guard_calls ac where ac.request_id=p_id and ac.state='settled')
    or exists(select 1 from public.ai_guard_calls ac where ac.request_id=p_id and ac.state='started') then
   return query select 'unavailable'::text,null::text,null::text,null::jsonb,null::text,null::text,null::timestamptz; return;
 end if;
 insert into public.explanation_format_commits(request_id,write_transaction,payload)
 values(p_id,txid_current(),jsonb_build_object('question_id',r.question_id,'explanation',p_explanation,'option_analysis',p_option_analysis,'memory_tip',p_memory_tip,'model',r.model,'updated_at',n,'reading_format','full-v1'));
 insert into public.question_explanation_overrides as eo(question_id,explanation,option_analysis,memory_tip,model,updated_at,reading_format)
 values(r.question_id,p_explanation,p_option_analysis,p_memory_tip,r.model,n,'full-v1')
 on conflict on constraint question_explanation_overrides_pkey do nothing returning eo.* into winner;
 inserted := found;
 if not inserted then
   select eo.* into winner from public.question_explanation_overrides eo where eo.question_id=r.question_id;
   if not found then return query select 'unavailable'::text,null::text,null::text,null::jsonb,null::text,null::text,null::timestamptz; return; end if;
 end if;
 update public.ai_guard_requests set result_committed=true where id=p_id;
 return query select case when inserted then 'inserted'::text else 'existing'::text end,
    winner.question_id,winner.explanation,winner.option_analysis,winner.memory_tip,winner.model,winner.updated_at;
end $function$

CREATE OR REPLACE FUNCTION public.explanation_reading_format_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if tg_op='INSERT' and new.reading_format is null then return new;end if;
 if tg_op='UPDATE' and old.reading_format is null and new.reading_format is null then return new;end if;
 if tg_op='DELETE' and old.reading_format is null then return old;end if;
 if tg_op='UPDATE' and (to_jsonb(old)-'figure_status')=(to_jsonb(new)-'figure_status') then return new;end if;
 if tg_op in ('UPDATE','DELETE') and old.replacement_revision is not null and exists(
 select 1 from public.explanation_replacement_versions v where v.request_id=old.replacement_revision
 and v.question_id=old.question_id and v.restore_transaction=txid_current() and v.restored_at is not null
 and (v.after_snapshot-'figure_status')=(to_jsonb(old)-'figure_status')
 and ((tg_op='DELETE' and v.restored_snapshot is null) or (tg_op='UPDATE' and v.restored_snapshot=to_jsonb(new)))
 ) then if tg_op='DELETE' then return old;else return new;end if;end if;
 if tg_op<>'DELETE' and new.reading_format='full-v1' then
 if exists(select 1 from public.explanation_format_commits f join public.ai_guard_requests r on r.id=f.request_id
 where f.write_transaction=txid_current() and r.state='active' and not r.result_committed and r.question_id=new.question_id
 and new.replacement_revision is null
 and f.payload=jsonb_build_object('question_id',new.question_id,'explanation',new.explanation,'option_analysis',new.option_analysis,'memory_tip',new.memory_tip,'model',new.model,'updated_at',new.updated_at,'reading_format',new.reading_format)) then return new;end if;
 if exists(select 1 from public.explanation_replacement_versions v join public.ai_guard_requests r on r.id=v.request_id
 where v.request_id=new.replacement_revision and v.write_transaction=txid_current() and v.committed_at is null
 and r.state='active' and not r.result_committed and r.actor_id=v.actor_id and r.question_id=new.question_id and v.question_id=new.question_id
 and v.after_snapshot=jsonb_build_object('explanation',new.explanation,'option_analysis',new.option_analysis,'memory_tip',new.memory_tip,'model',new.model,'replacement_revision',new.replacement_revision,'updated_at',new.updated_at,'figure_status',new.figure_status,'reading_format',new.reading_format)) then return new;end if;
 end if;
 raise exception 'trusted reading format commit required';
end$function$

CREATE OR REPLACE FUNCTION public.figure_image_claim_fresh(p_lease uuid, p_seconds integer, p_request uuid, p_question text, p_text_sha text)
 RETURNS TABLE(request_id uuid, question_id text, explanation_sha256 text, attempts integer)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare jid uuid; lim public.figure_image_limits%rowtype; cfg public.figure_queue_config%rowtype;
begin
 if p_lease is null or p_seconds is null or p_seconds not between 30 and 600
  or ((p_question is null)<>(p_text_sha is null))
  or (p_text_sha is not null and p_text_sha !~ '^[0-9a-f]{64}$') then return; end if;
 -- Same lock order as image capture: limits then config. Pausing cannot race
 -- this claim. Every external request still rechecks the runtime capture gate.
 select * into lim from public.figure_image_limits where id=true for share;
 if not found or not lim.enabled or not lim.capture then return; end if;
 select * into cfg from public.figure_queue_config where id=true for share;
 if not found or not cfg.enabled or not cfg.capture_new then return; end if;
 select j.request_id into jid from public.figure_queue_jobs j
 where j.state='pending' and j.attempts=0 and j.needs_state='approved'
  and j.figure_needs->>'status'='approved'
  and (p_request is null or j.request_id=p_request)
  and (p_question is null or (j.question_id=p_question and j.explanation_sha256=p_text_sha))
 order by j.created_at,j.request_id for update skip locked limit 1;
 if not found then return; end if;
 return query update public.figure_queue_jobs j set state='leased',attempts=1,lease_id=p_lease,
  lease_until=clock_timestamp()+make_interval(secs=>p_seconds),updated_at=clock_timestamp()
 where j.request_id=jid and j.state='pending' and j.attempts=0
 returning j.request_id,j.question_id,j.explanation_sha256,j.attempts;
end $function$

CREATE OR REPLACE FUNCTION figure_model_private.text_batch_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'figure_model_private'
AS $function$
DECLARE b figure_model_private.batch%rowtype; BEGIN
 -- ai_guard_reserve already owns the shared budget row; explicit lock also
 -- covers trusted direct fixture inserts. Same budget -> batch order as Luna.
 PERFORM 1 FROM public.ai_guard_budget WHERE id FOR UPDATE;
 IF TG_OP='INSERT' AND NEW.action_kind='explanation' AND NEW.call_limit=1 AND EXISTS(
  SELECT 1 FROM explanation_private.sitewide_requests s WHERE s.request_id=NEW.id
  AND s.actor_id=NEW.actor_id AND s.question_id=NEW.question_id AND s.action IN ('generate','replace')
  AND public.explanation_sitewide_allowed(s.actor_id,s.question_id)
 ) THEN RETURN NEW; END IF;
 SELECT * INTO b FROM figure_model_private.batch WHERE id FOR UPDATE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF NOT b.enabled THEN RAISE EXCEPTION 'bounded_text_batch_paused'; END IF;
 IF NOT coalesce(((b.funding_mode='cash_authorized' AND b.cash_authorized AND b.funding_evidence_sha ~ '^[0-9a-f]{64}$') OR (b.funding_mode='verified_credit' AND b.no_cash AND b.credit_until>clock_timestamp())),false) OR NEW.actor_id<>b.actor_id OR NOT NEW.question_id=ANY(b.targets)
  OR NEW.action_kind<>'explanation' OR NEW.call_limit<>1 OR b.text_requests>=3
  OR NEW.envelope_microusd<=0 OR b.charged+NEW.envelope_microusd>b.cap THEN
  RAISE EXCEPTION 'bounded_text_batch_denied'; END IF;
 INSERT INTO figure_model_private.text_reservations VALUES(NEW.id,NEW.question_id,NEW.envelope_microusd,clock_timestamp());
 UPDATE figure_model_private.batch SET charged=charged+NEW.envelope_microusd,text_requests=text_requests+1 WHERE id;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.figure_model_reserve(p_operation uuid, p_candidate uuid, p_key text, p_binding jsonb, p_model text, p_pricing text, p_cost bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'figure_model_private'
AS $function$
DECLARE b figure_model_private.batch%rowtype; a public.ai_guard_budget%rowtype;c public.explanation_figure_candidates%rowtype;
 j public.figure_queue_jobs%rowtype;o figure_model_private.operations%rowtype;txt text;token uuid;
BEGIN
 SELECT * INTO a FROM public.ai_guard_budget WHERE id FOR UPDATE;
 SELECT * INTO b FROM figure_model_private.batch WHERE id FOR UPDATE;
 IF NOT FOUND OR NOT b.enabled OR NOT b.model_enabled OR NOT coalesce(((b.funding_mode='cash_authorized' AND b.cash_authorized AND b.funding_evidence_sha ~ '^[0-9a-f]{64}$') OR (b.funding_mode='verified_credit' AND b.no_cash AND b.credit_until>clock_timestamp() AND a.verified_credit_expires_at>clock_timestamp())),false)
  OR a.enabled IS DISTINCT FROM true
  OR p_model IS DISTINCT FROM b.model OR p_pricing IS DISTINCT FROM b.pricing_revision OR p_cost IS DISTINCT FROM b.reserve_cost
  OR p_binding IS NULL OR jsonb_typeof(p_binding)<>'object' OR p_operation IS NULL OR p_key IS NULL OR p_key !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('status','unavailable'); END IF;
 SELECT * INTO o FROM figure_model_private.operations WHERE operation_id=p_operation OR candidate_id=p_candidate OR key=p_key LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('status',o.state,'dispatch',false,'operationId',o.operation_id); END IF;
 IF b.model_calls>=b.max_model_calls OR b.charged+p_cost>b.cap OR a.cap_microusd IS NULL OR a.spent_microusd+a.reserved_microusd+p_cost>a.cap_microusd THEN RETURN jsonb_build_object('status','budget'); END IF;
 IF NOT EXISTS(SELECT FROM public.figure_queue_config q,public.figure_image_limits l WHERE q.id AND l.id AND q.enabled AND q.capture_new AND l.enabled AND l.capture) THEN RETURN jsonb_build_object('status','paused'); END IF;
 PERFORM pg_advisory_xact_lock(hashtext('explanation-figure-review-v1'));
 SELECT * INTO c FROM public.explanation_figure_candidates WHERE id=p_candidate AND status='pending' FOR UPDATE;
 IF NOT FOUND OR (NOT c.question_id=ANY(b.targets) AND NOT EXISTS(SELECT 1 FROM explanation_private.sitewide_requests s JOIN public.ai_guard_requests r ON r.id=s.request_id WHERE s.request_id=(p_binding->>'requestId')::uuid AND s.question_id=c.question_id AND r.question_id=c.question_id AND r.result_committed AND public.explanation_sitewide_request_allowed(r.id,r.actor_id) AND EXISTS(SELECT 1 FROM public.figure_queue_jobs j WHERE j.request_id=r.id AND j.question_id=c.question_id AND j.explanation_sha256=c.explanation_sha256))) THEN RETURN jsonb_build_object('status','scope'); END IF;
 txt:=public.figure_model_locked_text(c.question_id,c.explanation_sha256);
 SELECT * INTO j FROM public.figure_queue_jobs WHERE request_id=(p_binding->>'requestId')::uuid FOR SHARE;
 IF NOT FOUND OR j.question_id<>c.question_id OR j.explanation_sha256<>c.explanation_sha256 OR j.needs_state<>'approved'
  OR NOT ((j.state='leased' AND j.attempts=1 AND (coalesce(p_binding->>'continuation','')='staged-image-v1' OR j.lease_until>clock_timestamp())) OR (j.state='done' AND public.figure_continuation_bound(p_binding,p_candidate)))
  OR (p_binding->>'policy') IS DISTINCT FROM 'luna-final-figure-v1' OR (p_binding->>'questionId') IS DISTINCT FROM c.question_id
  OR (p_binding->>'textHash') IS DISTINCT FROM c.explanation_sha256 OR (p_binding->>'sectionHash') IS DISTINCT FROM c.section_sha256
  OR (p_binding->>'imageHash') IS DISTINCT FROM c.image_sha256 OR coalesce(p_binding->>'questionHash','') !~ '^[0-9a-f]{64}$'
  OR coalesce(p_binding->>'sourceHash','') !~ '^[0-9a-f]{64}$'
  OR c.source_url !~ '^https://commons[.]wikimedia[.]org/wiki/File:[^[:space:]]+$'
  OR c.license_url IS DISTINCT FROM (CASE c.license WHEN 'CC BY 4.0' THEN 'https://creativecommons.org/licenses/by/4.0/' WHEN 'CC BY-SA 4.0' THEN 'https://creativecommons.org/licenses/by-sa/4.0/' WHEN 'CC BY 3.0' THEN 'https://creativecommons.org/licenses/by/3.0/' WHEN 'CC BY-SA 3.0' THEN 'https://creativecommons.org/licenses/by-sa/3.0/' WHEN 'CC0' THEN 'https://creativecommons.org/publicdomain/zero/1.0/' ELSE NULL END)
  OR c.license NOT IN ('CC BY 4.0','CC BY-SA 4.0','CC BY 3.0','CC BY-SA 3.0','CC0')
  OR NOT ((c.image_mime='image/png' AND substring(c.image_bytes from 1 for 8)=decode('89504e470d0a1a0a','hex')) OR (c.image_mime='image/jpeg' AND substring(c.image_bytes from 1 for 3)=decode('ffd8ff','hex')) OR (c.image_mime='image/webp' AND substring(c.image_bytes from 1 for 4)=convert_to('RIFF','UTF8') AND substring(c.image_bytes from 9 for 4)=convert_to('WEBP','UTF8')))
  OR txt IS NULL OR encode(sha256(convert_to(txt,'UTF8')),'hex')<>c.explanation_sha256
  OR encode(sha256(c.image_bytes),'hex')<>c.image_sha256 OR NOT public.ai_guard_image_eligible(c.question_id,c.explanation_sha256)
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(j.figure_needs->'items') i WHERE i->>'sectionHash'=c.section_sha256 AND i->>'sectionTitle'=c.section_heading AND i->>'caption'=c.section_title AND i->>'sectionAnchor'=c.section_anchor)
  OR NOT EXISTS(SELECT FROM regexp_split_to_table(txt,E'(?m)(?=^#{2,3}[ \t]+)') section WHERE encode(sha256(convert_to(btrim(section,E' \t\r\n'),'UTF8')),'hex')=c.section_sha256)
 THEN RETURN jsonb_build_object('status','stale'); END IF;
 token:=gen_random_uuid();
 INSERT INTO figure_model_private.operations(operation_id,key,candidate_id,binding,state,model,pricing_revision,reserved_cost,max_output_tokens,send_token,image_bytes,source_evidence)
 VALUES(p_operation,p_key,p_candidate,p_binding,'reserved',p_model,p_pricing,p_cost,b.max_output_tokens,token,c.image_bytes,
 jsonb_build_object('source',c.source_url,'licenseUrl',c.license_url,'license',c.license,'attribution',c.attribution,'mime',c.image_mime));
 UPDATE figure_model_private.batch SET charged=charged+p_cost,model_calls=model_calls+1 WHERE id;
 UPDATE public.ai_guard_budget SET reserved_microusd=reserved_microusd+p_cost WHERE id;
 INSERT INTO figure_model_private.events(operation_id,event) VALUES(p_operation,'reserved');
 RETURN jsonb_build_object('status','reserved','dispatch',false,'sendToken',token,'operationId',p_operation,'maxOutputTokens',b.max_output_tokens);
END $function$

CREATE OR REPLACE FUNCTION public.figure_model_sent(p_operation uuid, p_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'figure_model_private'
AS $function$
BEGIN
 PERFORM 1 FROM public.ai_guard_budget WHERE id AND enabled FOR SHARE;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM 1 FROM figure_model_private.batch b JOIN public.ai_guard_budget a ON a.id=b.id WHERE b.id AND b.enabled AND b.model_enabled AND coalesce(((b.funding_mode='cash_authorized' AND b.cash_authorized AND b.funding_evidence_sha ~ '^[0-9a-f]{64}$') OR (b.funding_mode='verified_credit' AND b.no_cash AND b.credit_until>clock_timestamp() AND a.verified_credit_expires_at>clock_timestamp())),false) FOR SHARE OF b;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM public.figure_queue_config q,public.figure_image_limits l WHERE q.id AND l.id AND q.enabled AND q.capture_new AND l.enabled AND l.capture) THEN RETURN false; END IF;
 -- A lost acknowledgement is a hold, not permission to repeat. No lease reset.
 UPDATE figure_model_private.operations SET state='sent',sent_at=clock_timestamp() WHERE operation_id=p_operation AND send_token=p_token AND state='reserved'
 AND EXISTS(SELECT FROM public.figure_queue_jobs j WHERE j.request_id=(binding->>'requestId')::uuid AND ((j.state='leased' AND j.attempts=1 AND (j.lease_until>clock_timestamp() OR (binding->>'continuation'='staged-image-v1' AND EXISTS(SELECT FROM public.explanation_figure_candidates c WHERE c.id=candidate_id AND c.status='pending' AND c.image_sha256=binding->>'imageHash' AND c.explanation_sha256=binding->>'textHash')))) OR (j.state='done' AND public.figure_continuation_bound(binding,candidate_id))));
 IF NOT FOUND THEN RETURN false; END IF;
 INSERT INTO figure_model_private.events(operation_id,event) VALUES(p_operation,'sent');RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.figure_model_commit(p_operation uuid, p_binding jsonb, p_verdict text, p_response text, p_response_sha text, p_cost bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'figure_model_private'
AS $function$
DECLARE o figure_model_private.operations%rowtype;c public.explanation_figure_candidates%rowtype;txt text;valid boolean; BEGIN
 PERFORM 1 FROM public.ai_guard_budget WHERE id FOR UPDATE;
 PERFORM 1 FROM figure_model_private.batch WHERE id FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtext('explanation-figure-review-v1'));
 SELECT * INTO o FROM figure_model_private.operations WHERE operation_id=p_operation FOR UPDATE;
 IF NOT FOUND OR o.binding IS DISTINCT FROM p_binding THEN RETURN jsonb_build_object('status','conflict'); END IF;
 IF o.state IN ('committed','stale') THEN
 IF o.verdict IS DISTINCT FROM p_verdict OR o.response_id IS DISTINCT FROM p_response OR o.response_sha IS DISTINCT FROM p_response_sha THEN RETURN jsonb_build_object('status','conflict'); END IF;
 RETURN jsonb_build_object('status',o.state,'committed',o.state='committed','verdict',o.verdict,'candidateStatus',(SELECT status FROM public.explanation_figure_candidates WHERE id=o.candidate_id));END IF;
 IF o.state NOT IN ('sent','unknown') OR p_verdict IS NULL OR p_response IS NULL OR p_response_sha IS NULL OR p_verdict NOT IN ('match','partial_match','mismatch') OR length(p_response) NOT BETWEEN 1 AND 200
  OR p_response_sha !~ '^[0-9a-f]{64}$' OR p_cost IS NULL OR p_cost<0 OR p_cost>o.reserved_cost THEN RETURN jsonb_build_object('status','invalid');END IF;
 SELECT * INTO c FROM public.explanation_figure_candidates WHERE id=o.candidate_id FOR UPDATE;
 txt:=public.figure_model_locked_text(c.question_id,c.explanation_sha256);
 valid:=c.status='pending' AND txt IS NOT NULL AND encode(sha256(convert_to(txt,'UTF8')),'hex')=c.explanation_sha256
  AND c.explanation_sha256=o.binding->>'textHash' AND c.section_sha256=o.binding->>'sectionHash' AND c.image_sha256=o.binding->>'imageHash'
  AND c.image_bytes=o.image_bytes AND encode(sha256(c.image_bytes),'hex')=c.image_sha256
  AND public.ai_guard_image_eligible(c.question_id,c.explanation_sha256)
  AND EXISTS(SELECT FROM public.figure_queue_jobs j WHERE j.request_id=(o.binding->>'requestId')::uuid
    AND j.question_id=c.question_id AND j.explanation_sha256=c.explanation_sha256 AND j.needs_state='approved'
    AND EXISTS(SELECT FROM jsonb_array_elements(j.figure_needs->'items') i WHERE i->>'sectionHash'=c.section_sha256
      AND i->>'sectionTitle'=c.section_heading AND i->>'caption'=c.section_title AND i->>'sectionAnchor'=c.section_anchor))
  AND jsonb_build_object('source',c.source_url,'licenseUrl',c.license_url,'license',c.license,'attribution',c.attribution,'mime',c.image_mime)=o.source_evidence;
 IF valid THEN
  UPDATE public.explanation_figure_candidates SET status=CASE WHEN p_verdict='mismatch' THEN 'rejected' ELSE 'approved' END,
   machine_review_id=o.operation_id,reviewed_at=clock_timestamp(),image_bytes=CASE WHEN p_verdict='mismatch' THEN NULL ELSE image_bytes END WHERE id=c.id;
  IF p_verdict<>'mismatch' THEN
   UPDATE public.figure_queue_jobs SET state='done',image_status='approved',lease_id=NULL,lease_until=NULL,updated_at=clock_timestamp()
    WHERE request_id=(o.binding->>'requestId')::uuid AND question_id=c.question_id AND explanation_sha256=c.explanation_sha256 AND state='leased';
  END IF;
 END IF;
 UPDATE figure_model_private.operations SET state=CASE WHEN valid THEN 'committed' ELSE 'stale' END,verdict=p_verdict,
  response_id=p_response,response_sha=p_response_sha,observed_cost=p_cost,settled_at=clock_timestamp() WHERE operation_id=p_operation;
 -- Charge the full known reservation conservatively. observed_cost is evidence,
 -- not a refund permission; unknown holds its full reservation until reconciled.
 UPDATE public.ai_guard_budget SET reserved_microusd=reserved_microusd-o.reserved_cost,spent_microusd=spent_microusd+o.reserved_cost WHERE id;
 INSERT INTO figure_model_private.events(operation_id,event,evidence_sha) VALUES(p_operation,CASE WHEN valid THEN p_verdict ELSE 'stale' END,p_response_sha);
 RETURN jsonb_build_object('status',CASE WHEN valid THEN 'committed' ELSE 'stale' END,'committed',valid,'verdict',p_verdict);
END $function$

CREATE OR REPLACE FUNCTION public.figure_text_commit_write(p_id uuid, p_actor uuid)
 RETURNS question_explanation_overrides
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.ai_guard_requests%rowtype;v public.explanation_replacement_versions%rowtype;
 p jsonb; shared jsonb; reviewed jsonb; current_base text;winner public.question_explanation_overrides%rowtype;
BEGIN
 SELECT * INTO r FROM public.ai_guard_requests WHERE id=p_id FOR UPDATE;
 SELECT * INTO v FROM public.explanation_replacement_versions WHERE request_id=p_id AND actor_id=p_actor FOR UPDATE;
 SELECT to_jsonb(e) INTO shared FROM public.question_explanation_overrides e WHERE question_id=r.question_id;
 SELECT jsonb_build_object('question_id',r.question_id,'generation',s.generation,'manifest_sha256',s.manifest_sha256,'source_commit',s.source_commit) INTO reviewed FROM public.ai_guard_reviewed_state s JOIN public.ai_guard_reviewed_questions q ON q.generation=s.generation AND q.question_id=r.question_id WHERE s.id;
 current_base:=encode(sha256(convert_to(jsonb_build_object('shared',shared,'reviewed_static_ref',reviewed)::text,'UTF8')),'hex');
 IF r.id IS NULL OR v.request_id IS NULL OR r.actor_id IS DISTINCT FROM p_actor OR r.state<>'active' OR r.result_committed
 OR v.write_transaction IS DISTINCT FROM txid_current() OR v.committed_at IS NOT NULL
 OR v.question_id<>r.question_id OR v.base_version IS DISTINCT FROM current_base
 OR NOT EXISTS(SELECT FROM public.ai_guard_calls WHERE request_id=p_id AND seq=1 AND state='settled')
 OR EXISTS(SELECT FROM public.ai_guard_calls WHERE request_id=p_id AND state<>'settled')
 OR NOT EXISTS(SELECT FROM public.ai_guard_reviewed_state WHERE id AND generation=r.reviewed_generation)
 THEN RAISE EXCEPTION 'exact replacement witness required';END IF;
 p:=v.after_snapshot;
 IF p->>'replacement_revision' IS DISTINCT FROM p_id::text OR p->>'model' IS DISTINCT FROM r.model
 OR p->>'reading_format' IS DISTINCT FROM 'full-v1' OR coalesce(length(p->>'explanation'),0) NOT BETWEEN 1 AND 100000
 OR jsonb_typeof(p->'option_analysis') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid exact payload';END IF;
 INSERT INTO public.question_explanation_overrides AS eo(question_id,explanation,option_analysis,memory_tip,model,updated_at,replacement_revision,figure_status,reading_format)
 VALUES(r.question_id,p->>'explanation',p->'option_analysis',p->>'memory_tip',r.model,(p->>'updated_at')::timestamptz,p_id,p->>'figure_status','full-v1')
 ON CONFLICT(question_id) DO UPDATE SET explanation=excluded.explanation,option_analysis=excluded.option_analysis,memory_tip=excluded.memory_tip,
 model=excluded.model,updated_at=excluded.updated_at,replacement_revision=excluded.replacement_revision,figure_status=excluded.figure_status,reading_format=excluded.reading_format
 RETURNING eo.* INTO winner;
 RETURN winner;
END$function$

CREATE OR REPLACE FUNCTION explanation_private.explanation_generation_status(p_id uuid, p_actor uuid, p_question text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'explanation_private'
AS $function$
declare r public.ai_guard_requests%rowtype; e public.question_explanation_overrides%rowtype;
begin
 select * into r from public.ai_guard_requests where id=p_id;
 if not found then return jsonb_build_object('status','missing');end if;
 if p_actor is null or r.actor_id is distinct from p_actor or r.question_id is distinct from p_question
 or exists(select 1 from public.explanation_replacement_versions where request_id=p_id) then return jsonb_build_object('status','denied');end if;
 if r.result_committed then
  select * into e from public.question_explanation_overrides where question_id=p_question;
  if found then return jsonb_build_object('status','completed','value',jsonb_build_object('question_id',e.question_id,'explanation',e.explanation,'option_analysis',e.option_analysis,'memory_tip',e.memory_tip,'model',e.model,'updated_at',e.updated_at,'reading_format',e.reading_format));end if;
 end if;
 return jsonb_build_object('status',case when r.state='closed' and not r.result_committed then 'not_written' else 'pending' end);
end $function$

CREATE OR REPLACE FUNCTION explanation_private.explanation_generation_recover(p_id uuid, p_actor uuid, p_question text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'explanation_private'
AS $function$
declare r public.ai_guard_requests%rowtype; j explanation_private.generation_results%rowtype; c public.ai_guard_calls%rowtype;
 result jsonb; settled text; current_status jsonb;
begin
 -- Match the existing table -> budget -> request order. No external transport.
 lock table public.question_explanation_overrides in share row exclusive mode;
 perform 1 from public.ai_guard_budget where id for update;
 select * into r from public.ai_guard_requests where id=p_id for update;
 if not found then return jsonb_build_object('status','missing');end if;
 if p_actor is null or r.actor_id is distinct from p_actor or r.question_id is distinct from p_question
 or exists(select 1 from public.explanation_replacement_versions where request_id=p_id) then return jsonb_build_object('status','denied');end if;
 current_status:=public.explanation_generation_status(p_id,p_actor,p_question);
 if current_status->>'status' in ('completed','not_written') then return current_status;end if;
 select * into j from explanation_private.generation_results where request_id=p_id and actor_id=p_actor;
 if not found then return jsonb_build_object('status','held_no_result');end if;
 if j.response_sha<>encode(sha256(convert_to(j.response::text,'UTF8')),'hex') then return jsonb_build_object('status','held_evidence_conflict');end if;
 if j.response->>'model' is distinct from r.model or coalesce(length(j.response->>'responseId'),0)=0
 or coalesce(j.response->'usage'->>'inputTokens','') !~ '^[0-9]+$'
 or coalesce(j.response->'usage'->>'outputTokens','') !~ '^[0-9]+$' then return jsonb_build_object('status','held_usage_unknown');end if;
 if (j.response->'usage'->>'inputTokens')::numeric>16000 or (j.response->'usage'->>'outputTokens')::numeric>2400 then return jsonb_build_object('status','held_usage_unknown');end if;
 select * into c from public.ai_guard_calls where request_id=p_id and seq=1;
 if c.state='started' then
  settled:=public.ai_guard_settle_call(p_id,1,r.per_call_ceiling_microusd,(j.response->'usage'->>'inputTokens')::bigint,(j.response->'usage'->>'outputTokens')::bigint);
  if settled<>'settled' then raise exception 'result settlement unconfirmed';end if;
 elsif c.state is distinct from 'settled' or c.cost_microusd<>r.per_call_ceiling_microusd
 or c.input_tokens<>(j.response->'usage'->>'inputTokens')::bigint or c.output_tokens<>(j.response->'usage'->>'outputTokens')::bigint then return jsonb_build_object('status','held_usage_conflict');end if;
 -- Save incomplete/invalid exact responses as evidence, but never publish them.
 if jsonb_typeof(j.response->'value') is distinct from 'object'
 or jsonb_typeof(j.response->'value'->'explanation') is distinct from 'string'
 or coalesce(length(trim(j.response->'value'->>'explanation')),0)=0
 or jsonb_typeof(j.response->'value'->'optionAnalysis') is distinct from 'object'
 or exists(select 1 from unnest(j.required_options) k where jsonb_typeof(j.response->'value'->'optionAnalysis'->k) is distinct from 'string' or coalesce(length(trim(j.response->'value'->'optionAnalysis'->>k)),0)=0) then
  if public.ai_guard_close(p_id)<>'closed' then raise exception 'result close unconfirmed';end if;
  return jsonb_build_object('status','not_written');
 end if;
 if jsonb_typeof(j.response->'needs')='object' then
  select to_jsonb(x) into result from public.figure_guard_commit_new_images(p_id,p_actor,j.response->'value'->>'explanation',j.response->'value'->'optionAnalysis',coalesce(j.response->'value'->>'memoryTip',''),j.response->'needs') x;
 else
  select to_jsonb(x) into result from public.ai_guard_commit(p_id,p_actor,j.response->'value'->>'explanation',j.response->'value'->'optionAnalysis',coalesce(j.response->'value'->>'memoryTip','')) x;
 end if;
 if coalesce(result->>'status','') not in ('inserted','existing') then return jsonb_build_object('status','held_commit');end if;
 if public.ai_guard_close(p_id)<>'closed' then raise exception 'result close unconfirmed';end if;
 return public.explanation_generation_status(p_id,p_actor,p_question);
end $function$

CREATE OR REPLACE FUNCTION explanation_private.explanation_sitewide_reserve(p_id uuid, p_actor uuid, p_question text, p_manifest_sha256 text, p_source_commit text, p_base_version text, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.ai_guard_budget%rowtype; v_review public.ai_guard_reviewed_state%rowtype; n timestamptz:=clock_timestamp();
begin
  select * into b from public.ai_guard_budget where id=true for update;
  if not found or not b.enabled or NOT public.explanation_sitewide_allowed(p_actor,p_question)
    or b.cap_microusd is null or b.envelope_microusd is null or b.max_calls is null
    or b.per_call_ceiling_microusd is null or b.per_call_ceiling_microusd::numeric*b.max_calls > b.envelope_microusd
    or b.max_parallel is null or b.max_actor_parallel is null or b.cooldown_seconds is null or b.hourly_limit is null or b.daily_limit is null
    or p_action is null or p_action not in ('generate','replace') or b.max_calls <> 1 or b.model is distinct from 'gpt-6.1-terra' or b.pricing_revision is null or p_id is null or p_actor is null
    or p_question is null or length(p_question) not between 1 and 200 then return 'unavailable'; end if;
  select * into v_review from public.ai_guard_reviewed_state where id=true;
  if not found or p_manifest_sha256 is distinct from v_review.manifest_sha256 or p_source_commit is distinct from v_review.source_commit then return 'review_snapshot_unavailable'; end if;
  if p_action='generate' and exists(select 1 from public.ai_guard_reviewed_questions where question_id=p_question and generation=v_review.generation) then return 'reviewed_protected';end if;
  if p_action='replace' and p_base_version is distinct from public.explanation_replacement_base(p_question)->>'version' then return 'replacement_version_changed'; end if;
  -- Duplicate ID never authorizes a second dispatch, even if retrying after uncertain RPC response.
  if exists(select 1 from public.ai_guard_requests where id=p_id) then return 'duplicate'; end if;
  if b.spent_microusd::numeric+b.reserved_microusd::numeric+b.envelope_microusd::numeric > b.cap_microusd then return 'budget'; end if;
  if exists(select 1 from public.ai_guard_requests where question_id=p_question and state='active') then return 'question_busy'; end if;
  if (select count(*) from public.ai_guard_requests where state='active') >= b.max_parallel then return 'busy'; end if;
  if (select count(*) from public.ai_guard_requests where state='active' and actor_id=p_actor) >= b.max_actor_parallel then return 'actor_busy'; end if;
  if exists(select 1 from public.ai_guard_requests where actor_id=p_actor and created_at > n-make_interval(secs=>b.cooldown_seconds)) then return 'cooldown'; end if;
  if (select count(*) from public.ai_guard_requests where actor_id=p_actor and created_at > n-interval '1 hour') >= b.hourly_limit
    or (select count(*) from public.ai_guard_requests where actor_id=p_actor and created_at > n-interval '24 hours') >= b.daily_limit then return 'rate'; end if;
  insert into explanation_private.sitewide_requests(request_id,actor_id,question_id,action) values(p_id,p_actor,p_question,p_action);
  insert into public.ai_guard_requests(id,actor_id,question_id,envelope_microusd,call_limit,per_call_ceiling_microusd,model,pricing_revision,reviewed_generation)
    values(p_id,p_actor,p_question,b.envelope_microusd,b.max_calls,b.per_call_ceiling_microusd,b.model,b.pricing_revision,v_review.generation);
  if p_action='replace' then
  insert into public.explanation_replacement_versions(request_id, actor_id, question_id, base_version, before_snapshot)
  values(p_id,p_actor,p_question,p_base_version,public.explanation_replacement_base(p_question));
  end if;
  update public.ai_guard_budget set reserved_microusd=reserved_microusd+b.envelope_microusd where id=true;
  return 'reserved';
end $function$

CREATE OR REPLACE FUNCTION explanation_private.explanation_sitewide_result_recover(p_id uuid, p_actor uuid, p_question text)
