 select * into j from explanation_private.generation_results where request_id=p_id and actor_id=p_actor;
 if not found then return jsonb_build_object('status','held_no_result');end if;
 if j.response_sha<>encode(sha256(convert_to(j.response::text,'UTF8')),'hex') then return jsonb_build_object('status','held_evidence_conflict');end if;
 if j.response->>'model' is distinct from r.model or coalesce(length(j.response->>'responseId'),0)=0
 or coalesce(j.response->'usage'->>'inputTokens','') !~ '^[0-9]+$'
 or coalesce(j.response->'usage'->>'outputTokens','') !~ '^[0-9]+$' then return jsonb_build_object('status','held_usage_unknown');end if;
 if (j.response->'usage'->>'inputTokens')::numeric>16000 or (j.response->'usage'->>'outputTokens')::numeric>2400 then return jsonb_build_object('status','held_usage_unknown');end if;
 select * into c from public.ai_guard_calls where request_id=p_id and seq=1;
 if c.state='started' then
  settled:=public.ai_guard_settle_call(p_id,1,r.per_call_ceiling_microusd,(j.response->'usage'->>'inputTokens')::bigint,(j.response->'usage'->>'outputTokens')::bigint);
  if settled<>'settled' then raise exception 'result settlement unconfirmed';end if;
 elsif c.state is distinct from 'settled' or c.cost_microusd<>r.per_call_ceiling_microusd
 or c.input_tokens<>(j.response->'usage'->>'inputTokens')::bigint or c.output_tokens<>(j.response->'usage'->>'outputTokens')::bigint then return jsonb_build_object('status','held_usage_conflict');end if;
 -- Save incomplete/invalid exact responses as evidence, but never publish them.
 if jsonb_typeof(j.response->'value') is distinct from 'object'
 or jsonb_typeof(j.response->'value'->'explanation') is distinct from 'string'
 or coalesce(length(trim(j.response->'value'->>'explanation')),0)=0
 or jsonb_typeof(j.response->'value'->'optionAnalysis') is distinct from 'object'
 or exists(select 1 from unnest(j.required_options) k where jsonb_typeof(j.response->'value'->'optionAnalysis'->k) is distinct from 'string' or coalesce(length(trim(j.response->'value'->'optionAnalysis'->>k)),0)=0) then
  if public.ai_guard_close(p_id)<>'closed' then raise exception 'result close unconfirmed';end if;
  return jsonb_build_object('status','not_written');
 end if;
 result:=public.ai_guard_commit_replacement(p_id,p_actor,j.response->'value'->>'explanation',j.response->'value'->'optionAnalysis',coalesce(j.response->'value'->>'memoryTip',''),nullif(j.response->'needs','null'::jsonb));
 if result->>'status'='replacement_version_changed' then
  if public.ai_guard_close(p_id)<>'closed' then raise exception 'result close unconfirmed';end if;
  return jsonb_build_object('status','not_written');
 end if;
 if result->>'status' is distinct from 'replaced' then return jsonb_build_object('status','held_commit');end if;
 if public.ai_guard_close(p_id)<>'closed' then raise exception 'result close unconfirmed';end if;
 return public.explanation_replacement_status(p_actor,p_question,p_id);
end $function$

CREATE OR REPLACE FUNCTION public.ai_guard_start_call(p_id uuid, p_seq integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.ai_guard_requests%rowtype; b public.ai_guard_budget%rowtype;
begin
 select * into b from public.ai_guard_budget where id=true for update;
 if not found or not b.enabled then return 'unavailable'; end if;
 select * into r from public.ai_guard_requests where id=p_id for update;
 if not found or r.state <> 'active' or r.result_committed or p_seq is null or p_seq < 1 or p_seq > r.call_limit then return 'unavailable'; end if;
 if (b.verified_credit_expires_at is null or b.verified_credit_expires_at<=clock_timestamp()) AND NOT public.explanation_sitewide_request_allowed(r.id,r.actor_id) AND NOT EXISTS(SELECT FROM figure_model_private.text_plans p JOIN figure_model_private.text_reservations t ON t.request_id=p.request_id WHERE p.request_id=r.id AND public.figure_text_cash_allowed(p.request_id,p.actor_id,p.question_id,p.base_version)) then return 'unavailable';end if;
 if b.cap_microusd is null or b.spent_microusd::numeric+b.reserved_microusd::numeric > b.cap_microusd or b.model is distinct from r.model or b.pricing_revision is distinct from r.pricing_revision then return 'unavailable'; end if;
 if exists(select 1 from public.ai_guard_calls where request_id=p_id and (state='started' or seq=p_seq)) then return 'blocked'; end if;
 if p_seq <> (select count(*)+1 from public.ai_guard_calls where request_id=p_id) then return 'blocked'; end if;
 if (select coalesce(sum(cost_microusd),0) from public.ai_guard_calls where request_id=p_id)+r.per_call_ceiling_microusd > r.envelope_microusd then return 'budget'; end if;
 insert into public.ai_guard_calls(request_id,seq,state) values(p_id,p_seq,'started'); return 'started';
end $function$

CREATE OR REPLACE FUNCTION explanation_private.explanation_sitewide_hold_plan(p_id uuid, p_needs jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'explanation_private'
AS $function$
begin
 if octet_length(coalesce(p_needs,'null'::jsonb)::text)>4096 then return 'invalid';end if;
 perform 1 from public.figure_queue_jobs j join explanation_private.sitewide_requests s on s.request_id=j.request_id join public.ai_guard_requests r on r.id=s.request_id
 where j.request_id=p_id and j.state='pending' and j.attempts=0 and j.needs_state='awaiting' and j.figure_needs is not distinct from p_needs and r.result_committed and public.explanation_sitewide_request_allowed(r.id,r.actor_id) for update of j;
 if not found then return 'stale';end if;
 insert into explanation_private.sitewide_image_plan_holds(request_id,revision,reason) values(p_id,encode(sha256(convert_to(coalesce(p_needs,'null'::jsonb)::text,'UTF8')),'hex'),'invalid_schema_query') on conflict do nothing;
 return 'held';
end $function$

CREATE OR REPLACE FUNCTION public.ai_guard_settle_call(p_id uuid, p_seq integer, p_cost bigint, p_input bigint, p_output bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.ai_guard_requests%rowtype; b public.ai_guard_budget%rowtype;
begin
 select * into b from public.ai_guard_budget where id=true for update;
 if not found then return 'unavailable'; end if;
 select * into r from public.ai_guard_requests where id=p_id for update;
 if not found or r.state <> 'active' or p_cost is null or p_cost < 0 or p_input is null or p_input<0 or p_output is null or p_output<0 then return 'unavailable'; end if;
 update public.ai_guard_calls set state='settled',cost_microusd=p_cost,input_tokens=p_input,output_tokens=p_output,settled_at=clock_timestamp()
 where request_id=p_id and seq=p_seq and state='started';
 if not found then return 'duplicate_or_missing'; end if;
 if p_cost > r.per_call_ceiling_microusd or (select coalesce(sum(cost_microusd),0) from public.ai_guard_calls where request_id=p_id) > r.envelope_microusd then
   update public.ai_guard_budget set enabled=false,disabled_reason='usage_over_ceiling',disabled_at=clock_timestamp() where id=true; return 'overrun_disabled';
 end if;
 return 'settled';
end $function$

CREATE OR REPLACE FUNCTION public.ai_guard_close(p_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.ai_guard_budget%rowtype; r public.ai_guard_requests%rowtype; actual numeric;
begin
 select * into b from public.ai_guard_budget where id=true for update;
 if not found then return 'unavailable'; end if;
 select * into r from public.ai_guard_requests where id=p_id for update;
 if not found or r.state<>'active' then return 'unavailable'; end if;
 if exists(select 1 from public.ai_guard_calls where request_id=p_id and state='started') then return 'unresolved'; end if;
 if not exists(select 1 from public.ai_guard_calls where request_id=p_id) then return 'unstarted_requires_reconciliation'; end if;
 select coalesce(sum(cost_microusd),0) into actual from public.ai_guard_calls where request_id=p_id;
 -- Overflow or accounting inconsistency fails transaction and retains lock+reservation.
 if b.reserved_microusd<r.envelope_microusd then return 'unavailable'; end if;
 if actual > 9223372036854775807::numeric-b.spent_microusd then
   update public.ai_guard_budget set enabled=false,disabled_reason='cost_overflow',disabled_at=clock_timestamp() where id=true;
   return 'overflow_disabled';
 end if;
 update public.ai_guard_budget set reserved_microusd=reserved_microusd-r.envelope_microusd,
   spent_microusd=spent_microusd+actual::bigint, enabled=enabled and actual<=r.envelope_microusd,
   disabled_reason=case when actual>r.envelope_microusd then 'usage_over_ceiling' else disabled_reason end,
   disabled_at=case when actual>r.envelope_microusd then clock_timestamp() else disabled_at end where id=true;
 update public.ai_guard_requests set state='closed',closed_at=clock_timestamp() where id=p_id;
 return case when actual>r.envelope_microusd then 'overrun_disabled' else 'closed' end;
end $function$

CREATE OR REPLACE FUNCTION public.ai_guard_reviewed_write_barrier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.ai_guard_budget%rowtype; v_gen bigint; old_id text; new_id text;
 needs_version boolean:=false; exact_payload boolean:=false;
begin
 select * into b from public.ai_guard_budget where id=true for update;
 if not found then raise exception 'review snapshot unavailable'; end if;
 select generation into v_gen from public.ai_guard_reviewed_state where id=true;
 if not found then raise exception 'review snapshot unavailable'; end if;
 if tg_op in ('UPDATE','DELETE') then old_id:=old.question_id;needs_version:=old.replacement_revision is not null;end if;
 if tg_op in ('UPDATE','INSERT') then new_id:=new.question_id;needs_version:=needs_version or new.replacement_revision is not null;end if;
 needs_version:=needs_version or exists(select 1 from public.ai_guard_reviewed_questions where generation=v_gen and question_id in(old_id,new_id));
 if tg_op='UPDATE' and old.question_id<>new.question_id and needs_version then raise exception 'replacement cannot move question identity';end if;
 -- A restore is authorized only by the owner-bound RPC's exact archived snapshot
 -- in this transaction. Neither role claims nor a client-supplied flag can bypass it.
 if tg_op in ('UPDATE','DELETE') and old.replacement_revision is not null and exists(
 select 1 from public.explanation_replacement_versions v where v.request_id=old.replacement_revision
 and v.question_id=old.question_id and v.restore_transaction=txid_current() and v.restored_at is not null
 and (v.after_snapshot-'figure_status')=(to_jsonb(old)-'figure_status')
 and ((tg_op='DELETE' and v.restored_snapshot is null) or (tg_op='UPDATE' and v.restored_snapshot=to_jsonb(new)))
 ) then if tg_op='DELETE' then return old;else return new;end if;end if;
 if tg_op='UPDATE' and old.question_id=new.question_id and
 (to_jsonb(old)-'figure_status')=(to_jsonb(new)-'figure_status') then return new;end if;
 if tg_op<>'DELETE' and new.replacement_revision is not null then
 select exists(select 1 from public.explanation_replacement_versions v join public.ai_guard_requests r on r.id=v.request_id
 where v.request_id=new.replacement_revision and v.question_id=new.question_id and r.question_id=new.question_id
 and v.write_transaction=txid_current() and v.committed_at is null and r.state='active' and not r.result_committed
 and r.actor_id=v.actor_id and r.reviewed_generation=v_gen and
 v.after_snapshot = jsonb_build_object('explanation',new.explanation,'option_analysis',new.option_analysis,'memory_tip',new.memory_tip,
 'model',new.model,'replacement_revision',new.replacement_revision,'updated_at',new.updated_at,'figure_status',new.figure_status,'reading_format',new.reading_format)
 and exists(select 1 from public.ai_guard_calls c where c.request_id=r.id and c.seq=1 and c.state='settled')
 and not exists(select 1 from public.ai_guard_calls c where c.request_id=r.id and c.state<>'settled')) into exact_payload;
 end if;
 if needs_version and not exact_payload then raise exception 'explicit versioned replacement required';end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$
